<script>
// ============ 配置 ============
const SWARM_BASE = ''; // 相对路径或空字符串
const ANALYZER_OUTPUT = 'swarm_data.json';

// 模型颜色映射
const MODEL_COLORS = {
  'gpt56_sol_reasoning_xhigh': '#ef4444',
  'gpt56_sol_reasoning_high': '#f97316',
  'gpt56_sol': '#fbbf24',
  'es1_orange_o50_thinking_max': '#8b5cf6',
  'es1_orange_o50_thinking': '#a78bfa',
  'es1_orange_o50': '#c4b5fd',
  'seed-stable-reasoning-high': '#3b82f6',
  'seed-stable-reasoning': '#60a5fa',
  'seed-stable': '#93c5fd',
  'unknown': '#64748b'
};

const MODEL_SHORT = {
  'gpt56_sol_reasoning_xhigh': 'Sol-XH',
  'gpt56_sol_reasoning_high': 'Sol-H',
  'gpt56_sol': 'Sol',
  'es1_orange_o50_thinking_max': 'Org-Max',
  'es1_orange_o50_thinking': 'Org-T',
  'es1_orange_o50': 'Org',
  'seed-stable-reasoning-high': 'Seed-RH',
  'seed-stable-reasoning': 'Seed-R',
  'seed-stable': 'Seed',
  'unknown': '?'
};

let currentData = null;

// ============ 数据加载 ============
async function loadData() {
  try {
    const resp = await fetch(ANALYZER_OUTPUT, { cache: 'no-store' });
    if (resp.ok) {
      const data = await resp.json();
      currentData = data;
      renderAll(data);
      document.getElementById('lastUpdate').textContent =
        '更新于: ' + new Date(data.generated_at || Date.now()).toLocaleString();
      return;
    }
  } catch(e) {
    console.log('无法加载数据文件，使用模拟数据');
  }
  // 加载模拟数据作为 fallback
  loadSampleData();
}

function loadSampleData() {
  // 生成 36 个 agent 的示例数据
  const sample = {
    generated_at: new Date().toISOString(),
    globals: { total_agents: 36, total_outputs: 0, total_citations: 0, total_messages: 0, total_files_size: 0 },
    agent_stats: {},
    ranking: [],
    all_files: [],
    citations: [],
    messages: [],
    citation_graph: {},
    model_stats: {}
  };

  const models = [
    'gpt56_sol_reasoning_xhigh', 'gpt56_sol_reasoning_high', 'gpt56_sol',
    'es1_orange_o50_thinking_max', 'es1_orange_o50_thinking', 'es1_orange_o50',
    'seed-stable-reasoning-high', 'seed-stable-reasoning', 'seed-stable'
  ];

  for (let i = 1; i <= 36; i++) {
    const id = 'agent-' + String(i).padStart(3, '0');
    const modelIdx = Math.floor((i-1) / 4) % models.length;
    const model = models[modelIdx];
    sample.agent_stats[id] = {
      id, model,
      is_seed: i === 5 || i === 17 || i === 29,
      total_outputs: 0,
      outputs_by_category: {},
      total_size: 0,
      citing: [], cited_by: [],
      citing_count: 0, cited_by_count: 0,
      message_count: 0,
      activity_score: 0
    };
  }

  currentData = sample;
  renderAll(sample);
  document.getElementById('lastUpdate').textContent = '示例数据 (请运行 analyzer 生成真实数据)';
}

// ============ 渲染 ============
function renderAll(data) {
  renderStats(data);
  renderModelLegend(data);
  renderAgentGrid(data);
  renderRanking(data);
  renderGraph(data);
  renderMessages(data);
}

function renderStats(data) {
  const g = data.globals || {};
  document.getElementById('statAgents').textContent = g.total_agents || 0;
  document.getElementById('statOutputs').textContent = g.total_outputs || 0;
  document.getElementById('statCitations').textContent = g.total_citations || 0;
  document.getElementById('statMessages').textContent = g.total_messages || 0;
  const size = g.total_files_size || 0;
  document.getElementById('statSize').textContent =
    size > 1024*1024 ? (size/1024/1024).toFixed(1) + ' MB' :
    size > 1024 ? (size/1024).toFixed(1) + ' KB' : size + ' B';
}

function renderModelLegend(data) {
  const models = new Set();
  Object.values(data.agent_stats || {}).forEach(a => models.add(a.model));
  const legend = document.getElementById('modelLegend');
  legend.innerHTML = '';
  [...models].sort().forEach(m => {
    const item = document.createElement('div');
    item.className = 'legend-item';
    item.innerHTML = `<span class="legend-dot" style="background:${MODEL_COLORS[m] || '#64748b'}"></span>${MODEL_SHORT[m] || m}`;
    legend.appendChild(item);
  });
}

function renderAgentGrid(data) {
  const grid = document.getElementById('agentGrid');
  grid.innerHTML = '';
  const agents = data.agent_stats || {};
  const maxScore = Math.max(...Object.values(agents).map(a => a.activity_score || 0), 1);

  // 按 agent ID 排序
  const sorted = Object.keys(agents).sort((a, b) => {
    const na = parseInt(a.split('-')[1]);
    const nb = parseInt(b.split('-')[1]);
    return na - nb;
  });

  sorted.forEach(id => {
    const a = agents[id];
    const cell = document.createElement('div');
    cell.className = 'agent-cell' + (a.is_seed ? ' seed' : '') + (a.total_outputs > 0 ? ' active' : '');
    cell.onclick = () => showAgentDetail(id);

    const color = MODEL_COLORS[a.model] || '#64748b';
    const intensity = Math.min(1, (a.activity_score || 0) / maxScore);

    cell.innerHTML = `
      <div class="agent-id">${id}</div>
      <div class="agent-score" style="color:${color}; opacity:${0.4 + intensity*0.6}">${a.activity_score || 0}</div>
      <div class="agent-model">${MODEL_SHORT[a.model] || a.model}</div>
      <div class="agent-outputs">📦 ${a.total_outputs || 0} 产出</div>
    `;
    grid.appendChild(cell);
  });
}

function renderRanking(data) {
  const list = document.getElementById('rankList');
  list.innerHTML = '';
  const ranking = data.ranking || [];

  if (ranking.length === 0) {
    list.innerHTML = '<div class="empty-state">暂无排名数据</div>';
    return;
  }

  ranking.forEach((r, i) => {
    const item = document.createElement('div');
    item.className = 'rank-item ' + (i < 3 ? 'top-' + (i+1) : '');
    item.innerHTML = `
      <div class="rank-num">#${r.rank}</div>
      <div class="rank-info">
        <div class="rank-name">${r.id}</div>
        <div class="rank-model">${MODEL_SHORT[r.model] || r.model} · ${r.outputs} 产出 · ${r.cited_by} 被引</div>
      </div>
      <div class="rank-score">${r.score}</div>
    `;
    item.style.cursor = 'pointer';
    item.onclick = () => showAgentDetail(r.id);
    list.appendChild(item);
  });
}

function renderGraph(data) {
  const svg = document.getElementById('graphSvg');
  // 清除除 defs 外的所有内容
  [...svg.querySelectorAll('g, .link, .node')].forEach(el => el.remove());

  const agents = data.agent_stats || {};
  const citations = data.citations || [];
  const agentIds = Object.keys(agents);

  if (agentIds.length === 0) return;

  const rect = svg.getBoundingClientRect();
  const w = rect.width;
  const h = rect.height;
  const centerX = w / 2;
  const centerY = h / 2;

  // 环形布局
  const n = agentIds.length;
  const radius = Math.min(w, h) * 0.38;

  const positions = {};
  agentIds.forEach((id, i) => {
    const angle = (i / n) * Math.PI * 2 - Math.PI / 2;
    positions[id] = {
      x: centerX + radius * Math.cos(angle),
      y: centerY + radius * Math.sin(angle)
    };
  });

  // 画连线
  const maxScore = Math.max(...Object.values(agents).map(a => a.activity_score || 0), 1);
  citations.forEach(c => {
    const from = positions[c.citer];
    const to = positions[c.cited];
    if (!from || !to) return;

    const line = document.createElementNS('http://www.w3.org/2000/svg', 'path');
    // 弧线
    const dx = to.x - from.x;
    const dy = to.y - from.y;
    const dist = Math.sqrt(dx*dx + dy*dy);
    const curve = dist * 0.15;
    const midX = (from.x + to.x) / 2;
    const midY = (from.y + to.y) / 2;
    const nx = -dy / dist * curve;
    const ny = dx / dist * curve;

    // 箭头终点偏移 (沿连线方向退回节点半径)
    const nodeR = 12;
    const endX = to.x - (dx / dist) * nodeR;
    const endY = to.y - (dy / dist) * nodeR;
    const startX = from.x + (dx / dist) * nodeR;
    const startY = from.y + (dy / dist) * nodeR;

    line.setAttribute('d', `M ${startX} ${startY} Q ${midX + nx} ${midY + ny} ${endX} ${endY}`);
    line.setAttribute('class', 'link');
    svg.appendChild(line);
  });

  // 画节点
  agentIds.forEach(id => {
    const a = agents[id];
    const pos = positions[id];
    const g = document.createElementNS('http://www.w3.org/2000/svg', 'g');
    g.setAttribute('class', 'node');
    g.setAttribute('transform', `translate(${pos.x}, ${pos.y})`);
    g.style.cursor = 'pointer';

    const color = MODEL_COLORS[a.model] || '#64748b';
    const r = 8 + (a.activity_score || 0) / maxScore * 8;

    const circle = document.createElementNS('http://www.w3.org/2000/svg', 'circle');
    circle.setAttribute('r', r);
    circle.setAttribute('fill', color);
    circle.setAttribute('fill-opacity', 0.8);
    if (a.is_seed) {
      circle.setAttribute('stroke-dasharray', '3 2');
    }
    g.appendChild(circle);

    const text = document.createElementNS('http://www.w3.org/2000/svg', 'text');
    text.setAttribute('y', r + 12);
    text.textContent = id.replace('agent-', '');
    g.appendChild(text);

    g.onclick = () => showAgentDetail(id);
    svg.appendChild(g);
  });
}

function renderMessages(data) {
  const list = document.getElementById('msgList');
  const messages = (data.messages || []).slice().reverse().slice(0, 20);

  if (messages.length === 0) {
    list.innerHTML = '<div class="empty-state">暂无消息</div>';
    return;
  }

  list.innerHTML = '';
  messages.forEach(m => {
    const item = document.createElement('div');
    item.className = 'msg-item';
    const time = m.time ? new Date(m.time).toLocaleString() : '';
    item.innerHTML = `
      <div class="msg-header">
        <span class="msg-from">${m.from || 'unknown'} → ${m.to || 'all'}</span>
        <span class="msg-time">${time}</span>
      </div>
      <div class="msg-text">${escapeHtml(m.message || '')}</div>
    `;
    list.appendChild(item);
  });
}

// ============ 详情弹窗 ============
function showAgentDetail(agentId) {
  const a = currentData.agent_stats[agentId];
  if (!a) return;

  document.getElementById('modalTitle').textContent = agentId + ' 详情';

  const files = (currentData.all_files || []).filter(f => f.agent === agentId);

  let html = `
    <div class="modal-section">
      <h3>基本信息</h3>
      <div style="font-size:13px; color:#cbd5e1; line-height:1.8;">
        <div>模型: <span style="color:${MODEL_COLORS[a.model]||'#60a5fa'}">${a.model}</span>${a.is_seed ? ' 🌱 [SEED]' : ''}</div>
        <div>活跃度得分: <strong style="color:#60a5fa">${a.activity_score || 0}</strong></div>
        <div>总产出数: ${a.total_outputs || 0}</div>
        <div>总产出大小: ${formatSize(a.total_size || 0)}</div>
      </div>
    </div>
    <div class="modal-section">
      <h3>产出分类</h3>
      <div style="font-size:13px; color:#cbd5e1;">
        ${Object.entries(a.outputs_by_category || {}).map(([k,v]) =>
          `<span style="display:inline-block; margin-right:12px;">${k}: <strong>${v}</strong></span>`
        ).join('') || '<span style="color:#64748b;">暂无产出</span>'}
      </div>
    </div>
    <div class="modal-section">
      <h3>引用关系</h3>
      <div style="font-size:13px; color:#cbd5e1; line-height:1.8;">
        <div>引用了 ${a.citing_count || 0} 个 agent: ${(a.citing || []).join(', ') || '无'}</div>
        <div>被 ${a.cited_by_count || 0} 个 agent 引用: ${(a.cited_by || []).join(', ') || '无'}</div>
      </div>
    </div>
  `;

  if (files.length > 0) {
    html += `
      <div class="modal-section">
        <h3>产出文件 (${files.length})</h3>
        <div class="file-list">
          ${files.slice().sort((a,b) => b.mtime - a.mtime).map(f => `
            <div class="file-item">
              <span>${f.name}</span>
              <span class="cat">${f.category}</span>
            </div>
          `).join('')}
        </div>
      </div>
    `;
  }

  document.getElementById('modalContent').innerHTML = html;
  document.getElementById('modalOverlay').classList.add('show');
}

function closeModal() {
  document.getElementById('modalOverlay').classList.remove('show');
}

// ============ 工具函数 ============
function escapeHtml(str) {
  const div = document.createElement('div');
  div.textContent = str;
  return div.innerHTML;
}

function formatSize(bytes) {
  if (bytes > 1024*1024) return (bytes/1024/1024).toFixed(2) + ' MB';
  if (bytes > 1024) return (bytes/1024).toFixed(1) + ' KB';
  return bytes + ' B';
}

// 初始化
window.addEventListener('load', loadData);
window.addEventListener('resize', () => currentData && renderGraph(currentData));
</script>

</body>
</html>
"}

